"เอลนีโญ · แรงมาก":"El Niño · Very Strong",
"ฝนต่ำกว่าค่าปกติต่อเนื่อง — ปี 2541 แล้งหนักและอุณหภูมิสูงผิดปกติทั่วประเทศ":"Persistently below-normal rainfall — severe drought and abnormally high temperatures nationwide in Year 2541",
"ลานีญา · แรง":"La Niña · Strong",
"ฝนเหนือค่าปกติมาก → มหาอุทกภัย 2554 · ผู้ได้รับผลกระทบ 13.6 ล้านคน":"Rainfall far above normal → the Great Flood of 2554 · 13.6 million people affected",
"เอลนีโญ · แรงที่สุดในสถิติ ONI":"El Niño · Strongest in the ONI record",
"ภัยแล้งหนักปี 2559 · เม.ย. 2559 แม่ฮ่องสอน 44.6°C — สถิติร้อนสุดของไทยในขณะนั้น":"Severe drought in Year 2559 · Apr 2559 Mae Hong Son 44.6°C — Thailand's hottest record at the time",
"ลานีญา 3 ปีซ้อน (triple-dip)":"Three consecutive La Niña years (triple-dip)",
"ฝนมากต่อเนื่องหลายฤดู — น้ำท่วมหลายจังหวัดปี 2564 (พายุเตี้ยนหมู่) และปี 2565":"Heavy rain persisting across several seasons — flooding in many provinces in Year 2564 (Tropical Storm Dianmu) and Year 2565",
"15 เม.ย. 2566 จ.ตาก 45.4°C — ร้อนที่สุดเท่าที่ประเทศไทยเคยบันทึกไว้":"15 Apr 2566 Tak Province 45.4°C — the hottest ever recorded in Thailand",
"เอลนีโญ · คาดว่าแรงมาก":"El Niño · Expected to be Very Strong",
"คาด RONI ≥ +2.5":"Expected RONI ≥ +2.5",
"— กรมอุตุฯ เตือนช่วง ส.ค.–ต.ค. 2569 ฝนน้อยและร้อนกว่าปกติ · เสี่ยงน้ำต้นทุนไม่พอและฝุ่น PM2.5 หนักช่วงต้นปี 2570":"— The Meteorological Department warns that Aug–Oct 2569 will be drier and hotter than Normal · risk of insufficient reservoir water and heavy PM2.5 Dust in early 2570",
"มหาสมุทรเปลี่ยนอุณหภูมิ":"The Ocean Changes Temperature",
"ลมค้าตะวันออกอ่อนกำลังลง มวลน้ำอุ่นที่เคยถูกดันไปกองฝั่งตะวันตกไหลกลับมาทางตะวันออก — ภาพดาวเทียมของ NOAA จึงเห็นเป็นแถบแดงยาวพาดตามแนวศูนย์สูตร (เอลนีโญ) หรือแถบเย็นสีขาว–ฟ้า (ลานีญา)":"The easterly trade winds weaken, and the warm water mass that was once pushed to pile up on the western side flows back toward the East — so NOAA satellite imagery shows a long red band stretching along the equator (El Niño) or a cool white–blue band (La Niña)",
"บรรยากาศเหนือทะเลขยับตาม":"The Atmosphere Above the Sea Shifts Too",
"ตำแหน่งการยกตัวของอากาศและกลุ่มฝน (วอล์กเกอร์เซลล์) เลื่อนตามน้ำอุ่นไปทางตะวันออก — ฝั่งอินโดนีเซีย–ไทยจึงแห้งลงในปีเอลนีโญ และชุ่มขึ้นในปีลานีญา":"The position of rising air and rain clusters (Walker cell) moves East following the warm water — so Indonesia and Thailand become drier in El Niño years and wetter in La Niña years",
"กระแสลมกรดคดโค้ง":"The Jet Stream Meanders",
"ความร้อนที่ย้ายตำแหน่งไปดัดคลื่นในกระแสลมกรด (jet stream) ให้คดเป็นลอนลึกขึ้น ระบบอากาศจึงเคลื่อนตัวช้าลงและค้างอยู่ที่เดิมได้นานขึ้น":"Heat that has shifted position bends the waves in the jet stream into deeper loops, so weather systems move more slowly and can stay in the same place longer",
"ความกดอากาศสูงปิดกั้น → โดมความร้อน":"Blocking High Pressure → Heat Dome",
"เมื่อหย่อมความกดอากาศสูงหยุดนิ่งกลายเป็น blocking high (บนแผนที่คือวงความกดอากาศซ้อนกันรอบตัว H) อากาศจะจมตัว ฟ้าโปร่งไม่มีเมฆบัง แดดเผาพื้นซ้ำที่เดิมทุกวัน จนกลายเป็นคลื่นความร้อนยาวหลายวันถึงหลายสัปดาห์":"When a high-pressure area becomes Stationary and turns into a blocking high (on the map, the nested pressure rings around H), the air sinks, the sky is clear with no clouds to block it, and the sun bakes the same ground every day until it becomes a heat wave lasting several days to several weeks",
