"หนึ่งในเอลนีโญรุนแรงที่สุดเท่าที่วัดมา (ONI พีค +2.6°C) มวลน้ำร้อนแผ่เต็มแปซิฟิกตะวันออก ไทยแล้งจัด ฝนทิ้งช่วง ข้าวเสียหายรุนแรง และเกิดไฟป่าอินโดนีเซียครั้งใหญ่":"One of the strongest El Niños ever measured (ONI peak +2.6°C). A mass of warm water spread across the entire eastern Pacific; Thailand suffered severe drought and a long dry spell in the rainy season, Rice was badly damaged, and Indonesia had major forest fires.",
"อ่อนกำลัง / พัดย้อนกลับ (Westerly Bursts) 💨":"Weakened / reversed (Westerly Bursts) 💨",
"ลานีญากำลังแรงจัด (ONI พีค −1.7°C) ลิ้นน้ำเย็นทอดยาวตามแนวศูนย์สูตร ดันมวลน้ำอุ่นและความชื้นมาสะสมแถบอาเซียนและอ่าวไทย มรสุมชุกผิดปกติ นำไปสู่มหาอุทกภัย 2554 — ภาพที่เห็นคือค่าเฉลี่ยของปี 2011 ซึ่งเป็นปีที่สัญญาณลานีญาเด่นที่สุด":"A very strong La Niña (ONI peak −1.7°C). A tongue of cold water stretching along the equator pushed warm water and moisture to build up over ASEAN and the Gulf of Thailand, causing an unusually heavy monsoon and leading to the Great Flood of 2554. The image shown is the 2011 average, the year the La Niña signal was strongest.",
"พัดรุนแรงจัดเป็นประวัติการณ์ ➡️➡️➡️":"Blowing at record-breaking strength ➡️➡️➡️",
"ONI พีค +2.6°C เทียบเท่าปี 2540 อุณหภูมิผิวน้ำแปซิฟิกพุ่งทำลายสถิติ เกิดภัยแล้งรุนแรงในลุ่มน้ำเจ้าพระยา เขื่อนหลักเหลือน้ำใช้การต่ำสุดในรอบหลายสิบปี — ปี 2015 เป็นปีที่ค่าเฉลี่ยรายปีของ Niño 3.4 สูงที่สุดในกริดชุดนี้":"ONI peak +2.6°C, on par with 2540. Pacific sea surface temperatures spiked to record levels, causing severe drought in the Chao Phraya River Basin, and the main Dams were left with their lowest usable water in several decades — 2015 is the year with the highest annual average Niño 3.4 in this dataset.",
"อ่อนกำลังมาก / ผันผวน 💨":"Very weak / fluctuating 💨",
"2566–2567 (2023–24) · วิกฤตมหาสมุทรเดือด:":"2566–2567 (2023–24) · Boiling Ocean Crisis:",
"เอลนีโญ (ONI พีค +2.0°C) ที่ผสมกับภาวะโลกร้อน ทำให้อุณหภูมิมหาสมุทรโลกทำลายสถิติสูงสุดใหม่ต่อเนื่องกว่า 400 วัน และเกิดวิกฤตปะการังฟอกขาวครั้งที่ 4 ระดับโลก —":"An El Niño (ONI peak +2.0°C) combined with global warming pushed global ocean temperatures to new record highs for more than 400 days straight and triggered the 4th global coral bleaching crisis —",
"ลองกดปุ่มสลับโหมดดู:":"Try pressing the mode toggle button:",
"ค่าดิบขึ้น +1.1°C แต่พอหักแนวโน้มออกเหลือแค่ +0.2°C เพราะปีนั้นทะเลเขตร้อนอุ่นขึ้นพร้อมกันทั้งแถบ (และตัวเอลนีโญพีคช่วง พ.ย. 2566–ม.ค. 2567 คาบเกี่ยวสองปีปฏิทิน ค่าเฉลี่ยรายปีจึงเจือจาง)":"The raw value rises by +1.1°C, but once the trend is removed only +0.2°C remains, because that year the entire tropical ocean band warmed together (and the El Niño peak from Nov 2566 to Jan 2567 straddles two Calendar Years, so the annual average is diluted)",
"อ่อนกำลังลงอย่างเห็นได้ชัด 💨":"Noticeably weakened 💨",
"2568 (2025) · ปีล่าสุดที่ข้อมูลครบ 12 เดือน:":"2568 (2025) · Latest year with a full 12 months of data:",
"ตัวอย่างที่ชัดที่สุดว่าทำไมต้องหักแนวโน้มโลกร้อนออก — ค่าดิบของ Niño 3.4 อยู่ราว":"The clearest example of why the global-warming trend must be removed — the raw Niño 3.4 value is about",
"ดูเหมือนไม่มีอะไรเกิดขึ้น แต่พอหักค่าเฉลี่ยทะเลเขตร้อน (+0.71°C) ออก กลับเป็น":"which looks like nothing is happening, but after subtracting the tropical sea average (+0.71°C) it turns out to be",
"−0.7°C = ลานีญาชัดเจน":"−0.7°C = clear La Niña",
"ตรงกับสภาวะจริงของปีนั้น":"matching the real conditions of that year",
"พัดปานกลางค่อนข้างแรง ➡️➡️":"Blowing moderately strong ➡️➡️",
"2556 (2013) · ปีที่ ENSO เป็นกลางจริง:":"2556 (2013) · A real ENSO-neutral year:",
"ค่าเฉลี่ย Niño 3.4 เกือบเท่าศูนย์พอดี ใช้เป็นภาพอ้างอิงว่า “ไม่มีทั้งเอลนีโญและลานีญา” หน้าตาเป็นอย่างไร — ลิ้นน้ำเย็นตามแนวศูนย์สูตรยังอยู่ตามธรรมชาติจากน้ำผุดเย็นลึก (Upwelling) ที่ชายฝั่งเปรู":"The Niño 3.4 average is almost exactly zero, used as a Reference image of what “neither El Niño nor La Niña” looks like — the cold tongue along the equator is still there naturally, from deep cold upwelling (Upwelling) off the coast of Peru",
