"ออกจากทุกช่องบนแผนที่ เพื่อให้เห็นว่าที่ไหน “ร้อน/เย็นกว่าค่าเฉลี่ยเขตร้อนของปีนั้น” แทนที่จะเห็นแค่ว่าโลกร้อนขึ้นทุกปี — เป็นแนวคิดเดียวกับดัชนี RONI ของ NOAA แต่คำนวณเองจากกริดรายปีชุดนี้ ไม่ใช่ดัชนี RONI ทางการ":"from every cell on the map, so you can see where is “hotter/colder than that year's tropical average” rather than only seeing that the world warms every year — it is the same concept as NOAA's RONI index, but computed in-house from this annual grid dataset and is not the official RONI index",
"โหมดค่าดิบ: สีคือส่วนต่างจากค่าเฉลี่ยปี ค.ศ. 1951–1980 ตรง ๆ ซึ่งรวมแนวโน้มโลกร้อนไว้ด้วย ปีหลัง ค.ศ. 2000 จึงออกแดงเกือบทั้งมหาสมุทร · ตัวเลขในกรอบเป็นค่าเฉลี่ย":"Raw-value mode: the color is directly the difference from the CE 1951–1980 average, which includes the global-warming trend, so years after CE 2000 look Red across almost the whole ocean · the number in the box is the average",
"ของพื้นที่ Niño 3.4 ไม่ใช่ดัชนี ONI ทางการของ NOAA (ONI เป็นค่าเฉลี่ย 3 เดือน) ค่ารายปีจึงเบากว่าค่าพีคเสมอ":"of the Niño 3.4 area, not the official NOAA ONI index (ONI is a 3-month average), so the annual value is always milder than the peak value",
