"หัวใจของสายพานฝั่งแอตแลนติก น้ำอุ่นที่กัลฟ์สตรีมพามาถึงตรงนี้เย็นจัดจนหนักกว่าน้ำรอบข้าง แล้ว":"The heart of the Atlantic side of the conveyor belt. Warm water brought here by the Gulf Stream becomes so cold that it is heavier than the water around it, then",
