"เปราะบางที่สุดต่อน้ำจืดจากน้ำแข็งละลาย":"most vulnerable to freshwater from melting ice",
"— ปีที่หนาวจัดน้ำจะจมลึกเกิน 2 กิโลเมตร ส่วนปีที่อุ่นแทบไม่จมเลย":"— in very cold years the water sinks deeper than 2 kilometers, while in warm years it barely sinks at all",
"ทะเลเวดเดลล์":"Weddell Sea",
"โรงงานผลิตน้ำที่":"A factory producing the water that is",
"หนาแน่นที่สุดในโลก":"the densest in the world",
"— น้ำเย็นเกือบ −1 °C ที่ถูกน้ำแข็งทะเลคายเกลือใส่ จมลงไปนอนอยู่ก้นมหาสมุทรทุกใบ เรียกว่า “น้ำก้นสมุทรแอนตาร์กติก” (AABW)":"— water at nearly −1 °C, loaded with salt expelled by sea ice, sinks and settles on the floor of every ocean. It is called “Antarctic Bottom Water” (AABW)",
"ทะเลรอสส์":"Ross Sea",
"แหล่งกำเนิด AABW หลักอีกแห่ง ฝั่งแปซิฟิก น้ำที่จมจากตรงนี้ใช้เวลา":"The other main source of AABW, on the Pacific side. Water that sinks here takes",
"หลายร้อยปี":"hundreds of years",
"กว่าจะไหลไปถึงก้นมหาสมุทรแปซิฟิกเหนือ":"to flow all the way to the floor of the North Pacific",
"มหาสมุทรใต้ · ลมตะวันตกกำลังแรง":"Southern Ocean · Strong Westerlies",
"ทางออกใหญ่ที่สุดของน้ำลึกทั้งโลก":"The largest outlet for deep water in the entire world",
"ลมตะวันตกที่พัดวนรอบทวีปแอนตาร์กติกาโดยไม่มีแผ่นดินขวาง ดูดน้ำลึกขึ้นสู่ผิวได้ราว 20–30 ล้าน ลบ.ม./วินาที พร้อมกับดันคาร์บอนเก่าที่เก็บไว้ใต้ทะเลกลับขึ้นมาด้วย":"Westerly winds circling Antarctica with no land to block them pull deep water up to the surface at about 20–30 million m³/s, bringing the old carbon stored beneath the sea back up with it",
"แปซิฟิกเหนือ":"North Pacific",
"ปลายทางสุดท้ายของสายพาน น้ำลึกตรงนี้คือน้ำที่":"The final destination of the conveyor belt. The deep water here is the",
"“เก่า” ที่สุดในโลก":"“oldest” in the world",
"— วัดอายุด้วยคาร์บอนได้ราว 1,000–1,600 ปี นับจากครั้งสุดท้ายที่มันได้สัมผัสอากาศ":"— carbon dating puts its age at roughly 1,000–1,600 years since it last touched the air",
"ทะเลอาหรับ & มหาสมุทรอินเดีย":"Arabian Sea & Indian Ocean",
"ลมมรสุมพัดน้ำผิวออกจากฝั่ง น้ำลึกที่เย็นและอุดมสารอาหารจึงเอ่อขึ้นมาแทน — เป็นทั้งจุดที่สายพานโผล่ขึ้นผิว และเป็น":"Monsoon winds push surface water away from the coast, and cold, nutrient-rich deep water wells up to replace it — it is both a place where the conveyor belt surfaces and",
"แหล่งประมงสำคัญ":"an important fishing ground",
"ของภูมิภาค":"for the region",
"กัลฟ์สตรีม":"Gulf Stream",
"กระแสน้ำผิวที่แรงที่สุดสายหนึ่งของโลก ~30 ล้าน ลบ.ม./วินาที เร็วได้ถึง 2 เมตร/วินาที · แต่":"One of the strongest surface currents in the world, ~30 million m³/s, reaching speeds of up to 2 meters/sec · But",
"ตัวขับหลักของมันคือลม ไม่ใช่ความหนาแน่น":"its main driver is wind, not density",
"— สายพานเทอร์โมฮาไลน์แค่อาศัย “ทางร่วม” เส้นนี้ขึ้นเหนือเท่านั้น":"— the thermohaline conveyor belt merely uses this “shared route” to head north",
"แนวตรวจวัด RAPID 26.5°N":"RAPID 26.5°N Monitoring Array",
"แนวทุ่นและเครื่องวัดที่พาดขวางมหาสมุทรจากบาฮามาสถึงชายฝั่งแอฟริกา วัด AMOC ต่อเนื่องมาตั้งแต่ปี 2547 —":"A line of buoys and instruments stretching across the ocean from the Bahamas to the African coast, measuring the AMOC continuously since B.E. 2547 —",
"ตัวเลขสเวอร์ดรุปที่เห็นด้านบนมาจากแนวนี้":"the Sverdrup values shown above come from this array",
