"แบบจำลองระบบสุริยะ 3 มิติเต็มรูปแบบ (Solar Atlas) คำนวณตำแหน่งดาวเคราะห์ตามเวลาจริงด้วยองค์ประกอบวงโคจรเคปเลอร์ (Keplerian Elements) พื้นผิวดาวเคราะห์และดวงจันทร์สังเคราะห์ด้วย Procedural 3D Perlin Noise ไร้รอยต่อ พร้อมเทคนิค Dynamic Origin สลับ 3 Scene ซ้อนกันเพื่อรองรับมาตราส่วน 14 หลัก ตั้งแต่ระดับกิโลเมตรบนผิวดาวไปจนถึงเกลียวแขนของทางช้างเผือก (Milky Way Galaxy)":"A full 3D solar system model (Solar Atlas) that computes planetary positions in real time from Keplerian orbital elements. Planet and moon surfaces are synthesized seamlessly with Procedural 3D Perlin Noise, together with a Dynamic Origin technique that stacks 3 Scenes to support a scale of 14 orders of magnitude, from kilometers on a planet's surface to the spiral arms of the Milky Way Galaxy",
"เปิดแผนที่ระบบสุริยะ 3 มิติ (Solar Atlas) เต็มหน้าจอ (Fullscreen Edition)":"Open the 3D Solar System Map (Solar Atlas) in Fullscreen (Fullscreen Edition)",
"ซูมอิสระ 7 ระดับสเกล (ผิวดาว → กาแล็กซี) · คอนโซลเวลา Time Warp ปรับเร่ง/ย้อนเวลาสด · แผงข้อมูลวัตถุ · ค้นหาดาวเคราะห์ & ดวงจันทร์ · รองรับ 2 ภาษา (ไทย/EN)":"Free zoom across 7 scale levels (planet surface → galaxy) · Time Warp console to speed up/reverse time live · object info panel · search planets & moons · supports 2 languages (Thai/EN)",
"เปิดเต็มจอ ↗":"Open Fullscreen ↗",
"เทคโนโลยี: Three.js r128 + 3D Perlin Noise Procedural Shader + Keplerian Orbit Math · พัฒนาใหม่ทั้งหมดโดยอิสระสำหรับโครงการรัฐไทยก้าวหน้า":"Technology: Three.js r128 + 3D Perlin Noise Procedural Shader + Keplerian Orbit Math · Developed entirely from scratch and independently for the Ratthai Kaona project",
