"พื้นผิวสังเคราะห์ Procedural 3D":"Procedural 3D Synthetic Textures",
"คำนวณ Perlin Noise 3 มิติบนเวกเตอร์ทิศทางทรงกลมสดตอนเปิดหน้าเว็บ ไร้รอยต่อและไม่ยืดที่ขั้ว พร้อมสูตรระบายสีเฉพาะดวง: ลายพายุพฤหัสบดี หลุมอุกกาบาตดาวพุธ และรอยแตกน้ำแข็งยูโรปา":"Computes 3D Perlin Noise on spherical direction vectors live when the page opens, seamless and with no stretching at the poles, with body-specific coloring formulas: Jupiter's storm patterns, Mercury's craters, and Europa's ice fractures",
"คำนวณวงโคจรเคปเลอร์สด":"Live Kepler Orbit Computation",
"แก้สมการเคปเลอร์ E − e·sin E = M ด้วยวิธีนิวตัน (Newton-Raphson) 8 รอบจากองค์ประกอบวงโคจรยุค J2000 แม่นยำตามปฏิทินจริง ค.ศ. 1800–2050 พร้อมแถบ Time Scrub เล่น/หยุด/ถอยหลัง":"Solves Kepler's equation E − e·sin E = M using Newton-Raphson iteration (8 rounds) from J2000-epoch orbital elements, accurate to the real ephemeris for CE 1800–2050, with a Time Scrub bar to play/pause/reverse",
"แบบจำลองระบบสุริยะ 3 มิติ (3D Solar System Orrery & Comet Halley)":"3D Solar System Model (3D Solar System Orrery & Comet Halley)",
