"WebGL · Three.js 3D · อินเทอร์แอกทีฟ":"WebGL · Three.js 3D · Interactive",
"แบบจำลองกลศาสตร์ท้องฟ้า 3 มิติ (Orrery) ระดับความละเอียดสูง พร้อมดวงอาทิตย์สังเคราะห์ด้วย Procedural Canvas, ดาวเคราะห์ 8 ดวง + เมฆหมุนวนบนโลก Blue Marble, ดวงจันทร์บริวาร (โลก, พฤหัสบดี, เสาร์), แถบดาวเคราะห์น้อยนับหมื่นดวง และ":"A high-resolution 3D celestial mechanics model (Orrery), with a Sun synthesized using a Procedural Canvas, 8 planets + swirling clouds on the Blue Marble Earth, moons (Earth, Jupiter, Saturn), an asteroid belt of tens of thousands of objects, and",
"ดาวหางฮัลเลย์ 3D แท้":"a true 3D Halley's Comet",
