"เปิดแบบจำลองระบบสุริยะ 3 มิติ เต็มหน้าจอ (Fullscreen Edition)":"Open the 3D Solar System Model Fullscreen (Fullscreen Edition)",
"คลิกดวงดาวเพื่อเปิดการ์ดข้อมูลดาราศาสตร์ภาษาไทย · หมุน/ซูม 360° · แถบปรับสปีดเวลา Time Warp (1x–100x) · ปรับแสงสว่าง Flare และ Corona สด":"Click a celestial body to open an astronomy info card in Thai · rotate/zoom 360° · Time Warp speed slider (1x–100x) · adjust Flare and Corona brightness live",
"เทคโนโลยี: Three.js r128 + WebGL ACES Filmic Tone Mapping · ข้อมูลพิกัดและโมเดลพื้นผิวดาวเคราะห์จาก NASA 3D Resources · จัดทำโดยทีมงานรัฐไทยก้าวหน้า":"Technology: Three.js r128 + WebGL ACES Filmic Tone Mapping · Coordinate data and planetary surface models from NASA 3D Resources · Produced by the Ratthai Kaona team",
