"นักดาราศาสตร์ชาวอังกฤษ ได้ใช้กฎแรงโน้มถ่วงสากลของเซอร์ไอแซก นิวตัน คำนวณพบว่าดาวหางที่ปรากฏในปี 1531, 1607 และ 1682 แท้จริงคือดาวหางดวงเดียวกัน และทำนายว่ามันจะกลับมาอีกครั้งในปี 1758 แม้เขาจะเสียชีวิตก่อน แต่การกลับมาตามนัดทำให้กฎฟิสิกส์ของนิวตันได้รับการยอมรับทั่วโลก":"used Sir Isaac Newton's law of universal gravitation to calculate that the comets that appeared in 1531, 1607 and 1682 were in fact one and the same comet, and predicted that it would return in 1758. Although he died before then, its return on schedule led to worldwide acceptance of Newton's laws of physics",
