"ได้ครบทุกปีตั้งแต่ 2543 ถึง 2567 รวม 25 ปี (2549 คือปีเดียวกับคลิป NASA) — แถบสีของแต่ละปีคนละช่วงกัน เพราะค่าเฉลี่ยทั้งโลกไต่ขึ้นทุกปีไม่มีเว้นสักปี จาก 368 ppm เป็น 422 ppm หรือ +54 ppm ใน 24 ปี ·":"across every year from 2543 to 2567, 25 years in total (2549 is the same year as the NASA clip) — each year's color band covers a different range because the global average climbs every single year without a break, from 368 ppm to 422 ppm, or +54 ppm in 24 years ·",
