"(ชุด xCO2_1330LST · ค่า ณ เวลาท้องถิ่น 13:30 น. · กริด 3°×2° · ที่นี่หยิบมา 1 ภาพทุก 3 วัน รวมปีละ 122 ภาพ) · เส้นชายฝั่ง/พรมแดนจาก":"(xCO2_1330LST set · values at 13:30 local time · 3°×2° grid · here we take 1 image every 3 days, 122 images per year) · coastlines/borders from",
"(Natural Earth 110m) · CarbonTracker เป็นชุด":"(Natural Earth 110m) · CarbonTracker is a dataset that",
"ผสานข้อมูลตรวจวัดจริงเข้ากับแบบจำลองการไหลเวียนอากาศ":"blends actual measurements with an atmospheric circulation model,",
"ไม่ใช่การวัดตรงทุกจุด":"not a direct measurement at every point",
"ลมหายใจของโลก — แยกตามแถบละติจูด":"Earth's Breath — by Latitude Band",
"คำนวณสดจากกริดที่โหลดอยู่":"Calculated live from the loaded grid",
"เส้นแต่ละเส้นคือค่าเฉลี่ย CO₂ ของแถบละติจูดนั้นทั้งแถบ ไล่ไปตลอดปีที่เลือก · ยิ่งขึ้นไปทางเหนือ เส้นยิ่งแกว่งแรง เพราะแผ่นดินและป่าไม้ส่วนใหญ่ของโลกอยู่ซีกเหนือ — พอถึงฤดูใบไม้ผลิ-ร้อน ต้นไม้ดูดคาร์บอนจนค่าดิ่งลง แล้วพอใบร่วงเข้าฤดูหนาว การย่อยสลายก็คายคืนออกมา ส่วนแถบใต้สุดเกือบเป็นเส้นตรง":"Each line is the CO₂ average for that entire latitude band, run across the selected year · the farther north, the more strongly the line swings, because most of the world's land and forests are in the Northern Hemisphere — in spring and summer, trees absorb carbon and the value plunges, then when the leaves fall into winter, decomposition releases it back out, while the southernmost band is almost a straight line",
"คำนวณในเครื่องคุณจากไฟล์กริดของแผงด้านบน (ถ่วงน้ำหนักตามพื้นที่ด้วย cos ละติจูด) · เปลี่ยนปี/ชั้นอากาศด้านบนแล้วกราฟนี้จะคำนวณใหม่ตาม":"Calculated on your own machine from the grid file in the panel above (area-weighted by cos latitude) · change the year/air layer above and this chart recalculates accordingly",
"คลิปกับแผนที่ในหน้านี้ต่างกันตรงไหน":"How the Clip Differs from the Map on This Page",
"คลิป “A Year in the Life of Earth’s CO₂” ของ NASA ↗":"NASA's “A Year in the Life of Earth’s CO₂” clip ↗",
"GEOS-5 “Nature Run” ความละเอียดสูงมาก (NASA ระบุว่าละเอียดกว่าแบบจำลองภูมิอากาศทั่วไป 64 เท่า) จึงเห็นริ้ววงเล็ก ๆ ของลมชัดสวย แต่เป็นการ “ปล่อยให้แบบจำลองเดินเอง” ตลอดปี 2006":"GEOS-5 “Nature Run” at very high resolution (NASA states it is 64 times finer than typical climate models), so the small swirls of wind look vivid, but it is a model “left to run on its own” throughout 2006",
"แผนที่ในหน้านี้ =":"The map on this page =",
"ซึ่งดึงค่าที่สถานีตรวจวัดจริงทั่วโลกเข้ามาบังคับแบบจำลองเป็นระยะ ๆ ตัวเลขจึงยึดกับของจริง แต่กริดหยาบกว่ามาก (3°×2°) ภาพเลยเป็นปื้นนุ่ม ๆ ไม่มีริ้วย่อย":"which periodically pulls in readings from real monitoring stations worldwide to constrain the model, so the numbers are anchored to reality, but the grid is much coarser (3°×2°), so the image comes out as soft patches with no fine swirls",
"ทั้งสองอันเล่าเรื่องเดียวกัน: CO₂ ไม่ได้อยู่นิ่งเหนือประเทศที่ปล่อยมัน แต่ถูกลมพาไปทั้งโลกภายในไม่กี่สัปดาห์":"Both tell the same story: CO₂ does not sit still above the countries that emit it, but is carried around the whole world by the wind within a few weeks",
"ไฟล์ต้นทางเป็น NetCDF รายวันของ CarbonTracker CT2025 — หยิบมา 1 ไฟล์ทุก 3 วัน (122 ภาพต่อปี) ครบทุกปีตั้งแต่ 2000 ถึง 2024 รวม 3,050 ภาพต่อชั้นอากาศ ดาวน์โหลดได้ครบทุกวันที่ขอ ไม่มีวันไหนขาด · ชุดต้นทางมีถึง 11 ม.ค. 2025 ปี 2025 จึงยังไม่ครบปี":"The source files are daily CarbonTracker CT2025 NetCDF files — one file taken every 3 days (122 images per year), for every year from 2000 to 2024, totaling 3,050 images per air layer. Every requested date downloaded successfully, with no missing days · the source set runs only to 11 Jan 2025, so 2025 is not yet a complete year",
"เก็บค่าเป็นจำนวนเต็ม 1 ไบต์ต่อช่อง (มี min/scale กำกับในไฟล์ .json) ให้ไฟล์เล็กพอโหลดผ่านเว็บ — ปีละราว 1.3 MB ต่อชั้นอากาศ และจะโหลดเฉพาะชุดที่กดดูจริงเท่านั้น":"Values are stored as 1-byte integers per cell (with min/scale noted in the .json file) so the files are small enough to load over the web — about 1.3 MB per year per air layer, and only the set you actually open is loaded",
"ช่วงสีตัดค่าสุดโต่งบน-ล่างข้างละ 0.5% ทิ้ง ไม่งั้นจุดผิดปกติไม่กี่ช่องจะดึงสเกลจนทั้งแผนที่กลายเป็นสีเดียว":"The color range clips the top and bottom 0.5% of extreme values on each side; otherwise a few anomalous cells would stretch the scale until the whole map became a single color",
"ระหว่างสองภาพที่ห่างกัน 3 วัน แผนที่จะไล่สีต่อเนื่องให้ (interpolate) เพื่อให้ดูลื่นเหมือนคลิป — ค่าที่ทูลทิปอ่านได้เป็นค่าที่ผสมแล้วเช่นกัน":"Between two images 3 days apart, the map blends colors continuously (interpolates) so it looks as smooth as the clip — the values read in the tooltip are blended values as well",
