"ไว้ เพราะถ้าดูค่าดิบ ปีหลัง ค.ศ. 2000 จะแดงเกือบทั้งมหาสมุทรจนแยกเอลนีโญ–ลานีญาไม่ออก (กดปุ่มในแผงเพื่อสลับดูค่าดิบได้)":"is kept on, because with raw values the years after CE 2000 turn red across almost the entire ocean, making El Niño and La Niña impossible to tell apart (press the button in the panel to switch to raw values)",
