"แต่คำนวณเองจากกริดชุดนี้ โดยหักค่าเฉลี่ยผิวน้ำทะเลแถบ 20°S–20°N รายปี (แยกผืนน้ำออกจากพื้นดินด้วยรูปทวีปจากไฟล์ countries-110m ที่หน้านี้ใช้อยู่แล้ว) จึงไม่ใช่ค่า RONI ทางการ":"but computed from this grid itself, by subtracting the annual average sea surface temperature of the 20°S–20°N band (separating ocean from land using continent outlines from the countries-110m file already used on this page), so it is not the official RONI value",
"ความรู้เพิ่มเติม:":"Learn More:",
"ปรากฏการณ์":"The phenomenon of",
"เกิดจากปฏิสัมพันธ์ระหว่างบรรยากาศและมหาสมุทรแปซิฟิกเขตร้อน เมื่อลมสินค้า (Trade Winds) อ่อนแรง มวลน้ำอุ่นจะไหลย้อนกลับไปทางฝั่งเปรู ทำให้แถบเอเชียตะวันออกเฉียงใต้รวมถึงไทยเกิดความแห้งแล้งและฝนทิ้งช่วง ขณะที่หากลมสินค้าแรงจัด (ลานีญา) จะพัดมวลน้ำอุ่นมากองแถบอินโดนีเซีย-อ่าวไทย ก่อให้เกิดฝนตกชุกและพายุรุนแรง":"arises from interactions between the atmosphere and the tropical Pacific Ocean. When the Trade Winds weaken, warm water flows back toward Peru, causing drought and dry spells in Southeast Asia including Thailand. When the Trade Winds are very strong (La Niña), they push warm water to pile up around Indonesia and the Gulf of Thailand, causing heavy rain and severe storms.",
"เปรียบเทียบกับภาพถ่ายดาวเทียมจริงจาก NOAA (Equatorial Pacific SST Anomaly)":"Compare with Real Satellite Images from NOAA (Equatorial Pacific SST Anomaly)",
