"ภาพดาวเทียมของ NOAA แสดงพื้นที่":"NOAA satellite images show the area",
"มหาสมุทรแปซิฟิกแถบศูนย์สูตร (Equatorial Pacific)":"Equatorial Pacific Ocean (Equatorial Pacific)",
"บริเวณนอกชายฝั่งทวีปอเมริกาใต้ (เปรู, เอกวาดอร์, อเมริกากลาง) สังเกต \"ลิ้นน้ำเย็น (Cold Tongue)\" สีฟ้า-ขาวที่ทอดยาวเป็นแนวนอนไปทางทิศตะวันตกตามเส้นศูนย์สูตร ซึ่งถูกขนาบด้วยมวลน้ำอุ่นสีส้ม-แดง":"off the coast of South America (Peru, Ecuador, Central America). Note the blue-white \"Cold Tongue\" stretching horizontally westward along the Equator, flanked by orange-red warm water masses.",
