"จุดสังเกตสำคัญ:":"Key observation:",
"ลิ้นน้ำเย็นนี้เกิดขึ้นจากการที่ลมสินค้าพัดพามวลน้ำอุ่นไปทางทิศตะวันตก และเหนี่ยวนำให้เกิดน้ำผุดเย็นลึก (Upwelling) อุดมด้วยสารอาหารขึ้นมาจากใต้ทะเลเปรู เมื่อเกิดเอลนีโญ ลิ้นน้ำเย็นนี้จะหายไปและถูกแทนที่ด้วยมวลน้ำร้อนจัด ส่งผลกระทบต่อสภาพอากาศโลกทันที":"This cold tongue forms because the Trade Winds push warm water westward, inducing deep, cold, nutrient-rich upwelling (Upwelling) from beneath the sea off Peru. During El Niño, this cold tongue disappears and is replaced by extremely hot water, immediately affecting the world's climate.",
