"ดัชนีอุตสาหกรรมดาวโจนส์เริ่มจาก 66 จุดในปี 1900 ผ่านวิกฤตเศรษฐกิจตกต่ำใหญ่ปี 1929 ที่ดัชนีดิ่งลงถึง 89% (ต้องใช้เวลา 25 ปีจึงกลับมาเท่าเดิม) สู่การเติบโตของเศรษฐกิจยุคใหม่ ทะลุ 1,000 จุดในปี 1972, ทะลุ 10,000 จุดในปี 1999 และแตะระดับ 44,000+ จุดในปัจจุบัน":"The Dow Jones Industrial Average started at 66 points in 1900, passed through the Great Depression of 1929 when the index plunged 89% (taking 25 years to recover), and went on to the growth of the modern economy, breaking 1,000 points in 1972, breaking 10,000 points in 1999, and reaching 44,000+ points today",
