"ก่อนปี 1971 ผลิตภาพและค่าจ้างแรงงานเติบโตไปด้วยกันเกือบ 1:1 แต่หลังจากสหรัฐฯ ยกเลิกมาตรฐานทองคำและเข้าสู่ยุคการเงินสมัยใหม่ ผลิตภาพพุ่งขึ้นถึง +260% ขณะที่ค่าตอบแทนชั่วโมงทำงานจริงของคนทำงานทั่วไปโตเพียง +120% เกิดช่องว่างความมั่งคั่งมหาศาล":"Before 1971, productivity and labor wages grew together almost 1:1, but after the USA abandoned the gold standard and entered the modern financial era, productivity surged +260% while the real hourly compensation of typical workers grew only +120%, creating an enormous wealth gap",
"ที่มา: Economic Policy Institute (EPI) analysis of BLS and BEA data (wtfhappenedin1971.com)":"Source: Economic Policy Institute (EPI) analysis of BLS and BEA data (wtfhappenedin1971.com)",
