"จากยุคกำเนิดอุตสาหกรรมปิโตรเลียมที่ราคา $1.19/บาร์เรล ในปี 1900 สู่จุดเปลี่ยนสำคัญ: วิกฤตการณ์น้ำมัน 1973 และ 1979 ของกลุ่มโอเปกที่ผลักดันเงินเฟ้อทั่วโลก, พีคสูงสุด $147 ในปี 2008, วิกฤตราคาติดลบช่วงโควิด 2020 และการดีดตัวกลับช่วงสงครามรัสเซีย-ยูเครน":"From the birth of the petroleum industry at a price of $1.19/barrel in 1900 to key turning points: the 1973 and 1979 OPEC oil crises that pushed up inflation worldwide, the all-time peak of $147 in 2008, the negative-price crisis during COVID in 2020, and the rebound during the Russia-Ukraine war",
