"ภาพรวมเศรษฐศาสตร์":"Economics Overview",
"1. มนุษย์มีคุณภาพชีวิตและอายุขัยที่ก้าวกระโดด:":"1. Humans have seen a leap in quality of life and life expectancy:",
"วิทยาศาสตร์การแพทย์และสาธารณสุขทำให้มนุษย์มีอายุขัยเพิ่มขึ้นกว่าสองเท่าจากยุค 1900 โดยเฉพาะประเทศไทยที่สามารถยกระดับอายุขัยเฉลี่ยจาก 28.8 สู่กว่า 79 ปี":"Medical Science and Public Health have more than doubled human life expectancy since the 1900s, especially in Thailand, which raised average life expectancy from 28.8 to over 79 years",
"2. เงินสดไม่ใช่ที่เก็บมูลค่าระยะยาว:":"2. Cash is not a long-term store of value:",
"การละทิ้งมาตรฐานทองคำในปี 1971 นำไปสู่การขยายตัวของปริมาณเงินอย่างไร้ขีดจำกัด ทำให้เงินสดสูญเสียกำลังซื้ออย่างต่อเนื่อง สินทรัพย์ที่มีการผลิตจริง (หุ้น) หรือมีจำนวนจำกัดตามธรรมชาติ (ทองคำ, Bitcoin) จึงเป็นเกราะป้องกันความมั่งคั่งที่แท้จริง":"Abandoning the gold standard in 1971 led to an unlimited expansion of the money supply, causing cash to steadily lose purchasing power. Assets that are actually produced (stocks) or naturally limited in supply (gold, Bitcoin) are therefore a true shield for wealth",
"3. รอยแยกความเหลื่อมล้ำและภาระคนรุ่นใหม่:":"3. The inequality gap and the burden on the younger generation:",
"เมื่อผลตอบแทนของสินทรัพย์โตเร็วกว่าค่าจ้างแรงงาน (Piketty: r > g) ความเหลื่อมล้ำจึงถ่างกว้างขึ้น พร้อมกับต้นทุนปัจจัยสี่ เช่น ที่อยู่อาศัย ที่ต้องใช้เวลาทำงานแลกมามากกว่าคนรุ่นก่อนหลายเท่าตัว":"When asset returns grow faster than labor wages (Piketty: r > g), inequality widens, along with the cost of basic necessities such as housing, which now takes many times more working time to afford than it did for previous generations",
