"ผิวน้ำเป็นข้อมูลวันที่ 25 มี.ค. 2569 ส่วนชั้นน้ำลึกกับขึ้น–จมเป็นค่าเฉลี่ยเดือน ธ.ค. 2558 เพราะข้อมูลกระแสน้ำลึกทั้งโลกที่เปิดให้ใช้ฟรีมีถึงแค่ปีนั้น เทียบ “รูปแบบการไหล” กันได้ แต่ไม่ใช่ภาพของวันเดียวกัน":"The surface is data from 25 Mar 2569, while the deep layer and the rise–sink are the monthly average for Dec 2558, because the freely available global deep-current data only goes up to that year. The “flow patterns” can be compared, but they are not a picture of the same day",
