"เย็นลง":"cooling down",
"เค็มขึ้น":"becoming saltier",
"1 · น้ำอุ่นเดินทางขึ้นเหนือ":"1 · Warm water travels north",
"กัลฟ์สตรีมพาน้ำอุ่นจากเขตร้อนขึ้นไปถึงหน้ากรีนแลนด์และนอร์เวย์ ระหว่างทางมันปล่อยความร้อนออกสู่อากาศ — ความร้อนก้อนนี้เองที่ทำให้อังกฤษกับนอร์เวย์อุ่นกว่าแคนาดาที่ละติจูดเท่ากันหลายองศา":"The Gulf Stream carries warm water from the tropics up to off Greenland and Norway, releasing heat into the air along the way — this very heat is what makes England and Norway several degrees warmer than Canada at the same latitude",
"2 · เย็นจัด + น้ำแข็งขับเกลือออกมา":"2 · Extreme cold + ice squeezes out the salt",
"พอถึงขั้วโลก น้ำเย็นลงเกือบถึงจุดเยือกแข็ง และเมื่อผิวน้ำกลายเป็นน้ำแข็งทะเล เกลือจะถูก “คายทิ้ง” ลงในน้ำข้างใต้ (brine rejection) น้ำตรงนั้นจึงทั้งเย็นและเค็มกว่าปกติ":"Upon reaching the poles, the water cools to nearly freezing, and when the surface water turns into sea ice, the salt is “spat out” into the water below (brine rejection), so the water there is both colder and saltier than normal",
"3 · หนักจนจมลงก้นสมุทร":"3 · Heavy enough to sink to the seabed",
"เย็น + เค็ม = หนาแน่นที่สุด น้ำก้อนนี้จมดิ่งลงไป 2–4 กิโลเมตร กลายเป็น “น้ำลึกแอตแลนติกเหนือ” (NADW) แล้วไหลลงใต้ไปตามขอบตะวันตกของมหาสมุทร":"Cold + salty = densest. This body of water plunges 2–4 kilometers, becoming “North Atlantic Deep Water” (NADW), then flows south along the West edge of the ocean",
"4 · เอ่อกลับขึ้นผิว ครบวง":"4 · Upwelling back to the surface, completing the loop",
"ลมตะวันตกกำลังแรงรอบทวีปแอนตาร์กติกาดูดน้ำลึกกลับขึ้นสู่ผิว อีกส่วนค่อย ๆ ผสมขึ้นในแปซิฟิกกับอินเดีย แล้วไหลกลับเป็นน้ำอุ่นบนผิว — ครบวงในราวหนึ่งพันปี":"Strong westerly winds around Antarctica pull deep water back up to the surface. Another part gradually mixes upward in the Pacific and Indian Oceans, then flows back as warm surface water — completing the loop in about a thousand years",
"ลองเอง: น้ำแบบไหนถึงจะจม":"Try It Yourself: What Kind of Water Sinks",
