"ชุดเดียวกับลูกโลกด้านบน โดยส่งพิกัดปัจจุบันของจุดอ้างอิงเข้าโมเดล PALEOMAP แล้วอ่านค่ากลับทีละยุค · เส้นนี้แทน":"the same set as the globe above, by feeding the current coordinates of the reference point into the PALEOMAP model and reading the values back era by era · this line represents",
"แผ่นเปลือกโลกที่รองรับประเทศไทย":"the tectonic plate that underlies Thailand",
"(แผ่นชานไทย–อินโดจีน) ไม่ใช่ตัวประเทศไทย ซึ่งเพิ่งมีรูปร่างอย่างที่เห็นในไม่กี่ล้านปีหลังนี้เอง ·":"(the Shan-Thai–Indochina plate), not the country of Thailand itself, which took on its familiar shape only within the last few million years ·",
"ข้อควรระวัง:":"Caution:",
"ช่วงก่อน 400 ล้านปีก่อน โมเดล PALEOMAP วางแผ่นนี้ไว้ในซีกโลกเหนือ ซึ่ง":"Before 400 million years ago, the PALEOMAP model places this plate in the Northern Hemisphere, which",
"ต่างจากงานวิจัยส่วนใหญ่":"differs from most research",
"ที่วางไว้ริมกอนด์วานาในซีกโลกใต้ (Metcalfe 2013 · Burrett et al. 2014) — หางเส้นช่วงนั้นจึงควรอ่านเป็นคำตอบของโมเดลนี้เท่านั้น ส่วนช่วง 0–300 ล้านปีก่อนซึ่งเป็นใจความหลักของหัวข้อนี้ สอดคล้องกับงานวิจัยกระแสหลัก":"that places it at the edge of Gondwana in the Southern Hemisphere (Metcalfe 2013 · Burrett et al. 2014) — so the tail of the line in that period should be read only as this model's answer, while the 0–300 million years ago range, which is the main point of this topic, is consistent with mainstream research",
"ทวีปไหนเดินทางไกลที่สุดใน 540 ล้านปี":"Which Continent Traveled Farthest in 540 Million Years",
"คำนวณสด":"Live Calculation",
"วัดจากจุดอ้างอิงหนึ่งจุดต่อทวีป โดยบวกระยะทางวงกลมใหญ่ระหว่างตำแหน่งของทุกช่วงเวลาที่เก็บไว้ต่อกัน —":"Measured from one reference point per continent, by adding up the great-circle distances between its positions at every stored time range —",
"ระยะทางสะสม":"cumulative distance",
"จึงมากกว่าระยะทางเส้นตรงจากจุดเริ่มถึงจุดจบเสมอ เพราะทวีปไม่ได้วิ่งเป็นเส้นตรง แต่วนไปวนมาตามการรวมและการแตกตัวของมหาทวีป":"is therefore always greater than the straight-line distance from start to finish, because continents do not travel in a straight line but wander around with the assembly and breakup of supercontinents",
"คำนวณในเครื่องคุณจากตำแหน่งจุดอ้างอิง 10 จุดที่ย้อนด้วยโมเดล PALEOMAP ·":"Calculated on your own device from the positions of 10 reference points traced back with the PALEOMAP model ·",
