"เพราะใช้จุดเดียวแทนทั้งทวีป และเก็บข้อมูลทุก 5 ล้านปีเท่านั้น ระยะจริงย่อมมากกว่านี้เล็กน้อย · ภาพรวมที่ได้ตรงกับที่ตำราธรณีวิทยาบอกไว้ คือกลุ่มที่เคยอยู่กอนด์วานา (อินเดีย ออสเตรเลีย แอนตาร์กติกา) เดินทางไกลกว่ากลุ่มลอเรเซียทางเหนือ":"because a single point stands in for the whole continent and data is stored only every 5 million years, so the real distance is somewhat greater · the overall picture matches what geology textbooks say, namely that the group that was once part of Gondwana (India, Australia, Antarctica) traveled farther than the Laurasian group in the north",
