"ที่ยังกว้างขึ้นเรื่อย ๆ จนถึงวันนี้ · ส่วนแผ่นดินไทยตอนนั้นขึ้นมาอยู่เหนือเส้นศูนย์สูตรแล้ว และเชื่อมติดกับเอเชียเรียบร้อย":"which keeps getting wider to this day · meanwhile Thailand's landmass had by then risen above the Equator and joined with Asia",
