"นิวรอน 1 ตัว คำนวณอะไร":"What 1 Neuron Calculates",
"ภาพที่ป้อน × น้ำหนักของนิวรอน = คะแนนรายจุด แล้วบวกรวมทั้ง 784 จุด บวกไบแอส ถ้าติดลบให้เป็น 0 (ReLU) — แค่นี้เองคือ \"นิวรอนเทียม\"":"Input image × neuron weights = a score for each pixel, then add up all 784 pixels, add the bias, and if the result is negative make it 0 (ReLU) — that is all an \"artificial neuron\" is",
"AI เรียนรู้ยังไง (Backpropagation)":"How AI Learns (Backpropagation)",
"ตอนเริ่ม น้ำหนักทุกตัวเป็นเลขสุ่ม — โครงข่ายทายมั่วเกือบหมด การ \"เรียนรู้\" คือวนทำ 4 อย่างซ้ำเป็นหมื่นรอบ:":"At the start, every weight is a random number — the network guesses almost entirely at random. \"Learning\" means repeating 4 things for tens of thousands of rounds:",
"① ทาย → ② วัดว่าผิดแค่ไหน (loss) → ③ ไล่ย้อนหลังหาว่าน้ำหนักแต่ละตัวควรขยับทางไหน (backpropagation = กฎลูกโซ่ของแคลคูลัส) → ④ ขยับน้ำหนักทุกตัวนิดเดียวไปทางที่ผิดน้อยลง (gradient descent)":"① Guess → ② Measure how wrong it is (loss) → ③ Trace backward to find which way each weight should move (backpropagation = the chain rule of calculus) → ④ Nudge every weight a tiny bit in the direction that makes it less wrong (gradient descent)",
