"ในแผนที่นี้มีความหมาย — ทิศจาก man ไป woman เกือบขนานกับทิศจาก king ไป queen จนเอาเวกเตอร์มาบวกลบกันได้ · ข้อมูลในหัวข้อนี้คือเวกเตอร์ GloVe จริง 300 มิติ ของคำ 225 คำ":" on this map carry meaning — the direction from man to woman is nearly parallel to the direction from king to queen, so vectors can be added and subtracted · The data in this section is real 300-dimensional GloVe vectors for 225 words",
