"(หัวใจของสถาปัตยกรรม Transformer) ให้ทุกคำ \"ถาม\" (Query) และทุกคำ \"ประกาศตัว\" (Key) ถ้าตรงกันก็ดึงข้อมูล (Value) ของอีกคำมาผสม · GPT-2 small มีกลไกนี้":"(the heart of the Transformer architecture) lets every word \"ask\" (Query) and every word \"announce itself\" (Key); if they match, it pulls in the other word's data (Value) and blends it in · GPT-2 small has this mechanism:",
