"กฎของ Gompertz ระบุว่าอัตราการเสียชีวิตตามธรรมชาติของมนุษย์เพิ่มขึ้นแบบทวีคูณ (Exponential) ทุกๆ 8 ปี นักคณิตศาสตร์ประกันภัยใช้ตารางมรณกรรม (Life Tables) ร่วมกับการคิดลดมูลค่าปัจจุบัน (Actuarial Present Value) เพื่อคำนวณเบี้ยประกันและวางแผนกองทุนประกันสังคม":"Gompertz's law states that the natural human death rate increases exponentially (Exponential) every 8 years. Actuaries use mortality tables (Life Tables) together with discounting to present value (Actuarial Present Value) to calculate insurance premiums and plan social security funds",
