"คลื่นและพลังงานที่ขับเคลื่อนจักรวาล:":"Waves and energy that drive the universe:",
"สมการเชิงอนุพันธ์ย่อยของคลื่นบรรยายการสั่นสะเทือนของทุกสรรพสิ่ง ตั้งแต่เสียง คลื่นน้ำ ไปจนถึงคลื่นแม่เหล็กไฟฟ้า (แสง/วิทยุ) และเมื่อผนวกเข้ากับสมการสัมพัทธภาพของไอน์สไตน์ $E = mc^2$ ทำให้มนุษย์เข้าใจว่ามวลสารคือพลังงานที่ถูกอัดแน่น นำไปสู่พลังงานนิวเคลียร์และกลไกการส่องสว่างของดวงอาทิตย์":"The partial differential wave equation describes the vibration of everything, from sound and water waves to electromagnetic waves (light/radio). When combined with Einstein's relativity equation $E = mc^2$, humanity came to understand that matter is condensed energy, leading to nuclear energy and the mechanism by which the Sun shines",
