"เมตร/วินาที (ความเร็วแสง = กม./วินาที)":"meters/sec (speed of light = km/sec)",
"สมการคลื่นควบคุมพฤติกรรมของคลื่นทุกชนิดในธรรมชาติ — จากคลื่นเสียงในอากาศ (343 m/s) สู่คลื่นแสงในสุญญากาศ (299,792 km/s)":"The wave equation governs the behavior of every kind of wave in nature — from sound waves in air (343 m/s) to light waves in a vacuum (299,792 km/s)",
"ที่มา: Jean le Rond d'Alembert (1746) Wave Equation / Albert Einstein (1905) Ann. Phys.":"Source: Jean le Rond d'Alembert (1746) Wave Equation / Albert Einstein (1905) Ann. Phys.",
"สูตรคณิตศาสตร์ & โมเดลจำลอง":"Math Formulas & Simulation Models",
"กลศาสตร์ควอนตัม & ฟิสิกส์อนุภาค (Quantum Mechanics & Standard Model)":"Quantum Mechanics & Particle Physics (Quantum Mechanics & Standard Model)",
"โลกเร้นลับระดับอะตอมที่ขับเคลื่อนจักรวาล:":"The hidden atomic-scale world that drives the universe:",
"ฟิสิกส์ควอนตัมอธิบายพฤติกรรมของสสารและแสงในสเกลที่เล็กที่สุด ซึ่งอนุภาคมีคุณสมบัติเป็นทั้งคลื่นและอนุภาค (Wave-Particle Duality) อนุภาคไม่ได้มีตำแหน่งที่แน่นอน แต่เป็นกลุ่มหมอกความน่าจะเป็น $\\vert\\psi\\vert^2$ และสามารถทะลุผ่านกำแพงพลังงานที่ฟิสิกส์ดั้งเดิมห้ามไว้ได้ (Quantum Tunneling) ซึ่งเป็นกลไกที่ทำให้ดวงอาทิตย์เกิดฟิวชันและทำให้ชิปคอมพิวเตอร์และเซมิคอนดักเตอร์ทำงานได้":"Quantum physics explains the behavior of matter and light at the smallest scales, where particles are both waves and particles (Wave-Particle Duality). A particle has no definite position but is a cloud of probability $\\vert\\psi\\vert^2$, and can pass through energy barriers that classical physics forbids (Quantum Tunneling), which is the mechanism that lets the Sun undergo fusion and lets computer chips and semiconductors work",
"สมการชเรอดิงเงอร์ ควบคุมวิวัฒนาการของฟังก์ชันคลื่นตามเวลา":"The Schrödinger equation governs the time evolution of the wave function",
"หลักความไม่แน่นอนไฮเซนเบิร์ก ยิ่งรู้ตำแหน่งแม่น ยิ่งไม่รู้ความเร็ว":"Heisenberg's uncertainty principle: the more precisely you know the position, the less you know the speed",
"สัมประสิทธิ์การทะลุผ่านกำแพงศักย์ (Quantum Tunneling Probability)":"Potential Barrier Transmission Coefficient (Quantum Tunneling Probability)",
