"เจมส์ เคลิร์ก แมกซ์เวลล์ รวมกฎของเกาส์ ฟาราเดย์ และแอมแปร์เข้าเป็นระบบสมการ 4 ข้อที่ทำนายการมีอยู่ของคลื่นแม่เหล็กไฟฟ้า และพิสูจน์ว่าแสงแท้จริงแล้วคือคลื่นแม่เหล็กไฟฟ้าที่เคลื่อนที่ด้วยความเร็ว $c = 1/\\sqrt{\\mu_0\\varepsilon_0}$ และเมื่อประจุเคลื่อนที่ตัดสนามแม่เหล็ก จะเกิดแรงลอเรนซ์ $\\vec{F} = q\\vec{v}\\times\\vec{B}$ ผลักให้ประจุหมุนวนเป็นเกลียวไซโคลตรอน":"James Clerk Maxwell combined the laws of Gauss, Faraday and Ampere into a system of 4 equations that predicts the existence of electromagnetic waves and proves that light is in fact an electromagnetic wave traveling at speed $c = 1/\\sqrt{\\mu_0\\varepsilon_0}$. And when a moving charge crosses a magnetic field, the Lorentz force $\\vec{F} = q\\vec{v}\\times\\vec{B}$ arises, pushing the charge into a cyclotron spiral",
"แรงลอเรนซ์กำหนดวิถีของประจุในสนามไฟฟ้าและแม่เหล็ก":"The Lorentz force determines the trajectory of charges in electric and magnetic fields",
