"อุณหพลศาสตร์ & เอนโทรปี (Thermodynamics, Entropy & Brownian Motion)":"Thermodynamics & Entropy (Thermodynamics, Entropy & Brownian Motion)",
"ลูกศรแห่งเวลาและความไร้ระเบียบของธรรมชาติ:":"The arrow of time and the disorder of nature:",
"อุณหพลศาสตร์อธิบายการถ่ายเทความร้อนและพลังงาน โดยกฎข้อที่ 2 ระบุว่าเอนโทรปี ($S$) หรือระดับความไร้ระเบียบของระบบปิดในจักรวาลจะเพิ่มขึ้นเสมอ ทำให้เราเห็นว่าเวลาเดินไปข้างหน้าเสมอ (แก้วแตกไม่สามารถรวมกลับเป็นแก้วใหม่ได้เอง) และสูตรเอนโทรปีของลุดวิก โบลต์ซมันน์ $S = k_B \\ln \\Omega$ เชื่อมโยงสถิติอนุภาคระดับจุลภาคเข้ากับอุณหภูมิระดับมหภาค":"Thermodynamics explains the transfer of heat and energy. The second law states that entropy ($S$), the degree of disorder of a closed system in the universe, always increases, so we see time always moving forward (a broken glass cannot reassemble itself into a new glass), and Ludwig Boltzmann's entropy formula $S = k_B \\ln \\Omega$ links microscopic particle statistics to macroscopic temperature",
"กฎแก๊สอุดมคติ ความดัน ปริมาตร อุณหภูมิแปรผันตรง":"The ideal gas law: pressure, volume and temperature are directly proportional",
"สูตรเอนโทรปีโบลต์ซมันน์ ยิ่งมีสถานะไมโครมาก เอนโทรปียิ่งสูง":"Boltzmann's entropy formula: the more microstates, the higher the entropy",
"ศูนย์สัมบูรณ์ (-273.15 °C) สสารหยุดการเคลื่อนไหวทั้งหมด":"Absolute zero (-273.15 °C), where matter stops all motion",
"ศูนย์สัมบูรณ์ (Absolute Zero)":"Absolute Zero",
"-273.15 °C อุณหภูมิที่ต่ำที่สุดในเอกภพตามกฎข้อที่ 3":"-273.15 °C, the lowest temperature in the universe according to the third law",
"ค่าคงที่โบลต์ซมันน์ (kB)":"Boltzmann Constant (kB)",
"สะพานเชื่อมระหว่างระดับโมเลกุลสู่อุณหภูมิ":"A bridge from the molecular level to temperature",
"ลูกศรแห่งเวลา (Arrow of Time)":"Arrow of Time",
