"ทฤษฎีที่จอห์น ฟอน นอยมันน์ และ จอห์น แนช พัฒนาขึ้นเพื่อทำความเข้าใจสถานการณ์ที่ผลลัพธ์ของแต่ละคนขึ้นอยู่กับการตัดสินใจของผู้อื่น เป็นรากฐานของเศรษฐศาสตร์ รัฐศาสตร์ และความมั่นคงยุคใหม่:":"A theory developed by John von Neumann and John Nash to understand situations where each person's results depend on the decisions of others, forming the foundation of modern economics, political science, and security:",
"ภาวะกลืนไม่เข้าคายไม่ออกของนักโทษ (Prisoner's Dilemma)":"Prisoner's Dilemma",
"แสดงให้เห็นว่าเมื่อบุคคลต่างคนต่างทำเพื่อผลประโยชน์สูงสุดของตนเองอย่างสมเหตุสมผล ผลลัพธ์สุดท้ายกลับแย่ลงสำหรับทุกคนเมื่อเทียบกับการร่วมมือกัน — เป็นโมเดลอธิบายปัญหาโลกร้อน การแข่งขันสะสมอาวุธ และโศกนาฏกรรมของทรัพยากรร่วม (Tragedy of the Commons)":"Shows that when individuals each rationally pursue their own maximum self-interest, the final result is worse for everyone compared with cooperating — a model that explains global warming, arms races, and the Tragedy of the Commons",
"ดุลยภาพแนช (Nash Equilibrium)":"Nash Equilibrium",
"สถานะที่ผู้เล่นทุกคนต่างเลือกยุทธศาสตร์ที่ดีที่สุดแล้ว เมื่อรู้ว่าคนอื่นเลือกอะไร และไม่มีใครได้ประโยชน์จากการเปลี่ยนยุทธศาสตร์เพียงลำพัง — ใช้ในการประมูลคลื่นความถี่ 5G, การออกแบบตลาด, และการเจรจาระหว่างประเทศ":"A state in which every player has already chosen their best strategy given what others choose, and no one gains by changing strategy alone — used in 5G spectrum auctions, market design, and international negotiations",
