"การตั้งคำถามต่อรากฐานที่สำคัญที่สุดของการมีชีวิตอยู่และความเป็นจริง:":"Questioning the most important foundations of existence and reality:",
"1. อภิปรัชญา (Metaphysics):":"1. Metaphysics:",
"\"ความจริงสูงสุดคืออะไร?\" ศึกษาธรรมชาติของความเป็นจริง ตัวตน เวลา พื้นที่ และการมีอยู่ (Ontology)":"\"What is ultimate reality?\" Studies the nature of reality, self, time, space, and existence (Ontology)",
"2. ญาณวิทยา (Epistemology):":"2. Epistemology:",
