"1. การบริหารและการปกครอง":"1. Administration and Governance",
"ยกเลิกระบบจตุสดมภ์ (เวียง วัง คลัง นา) และเจ้าเมืองประเทศราช":"Abolished the Chatusadom system (Wiang, Wang, Khlang, Na) and the rulers of tributary states",
"สถาปนา 12 กระทรวง มีเสนาบดีรับผิดชอบ และระบบเทศาภิบาล (มณฑล จังหวัด อำเภอ ตำบล หมู่บ้าน)":"Established 12 ministries headed by ministers, and the Thesaphiban system (monthon, Province, District, Subdistrict, Village)",
