"ราษฎรทุกคนกลายเป็นคนเสรี มีสิทธิเลือกประกอบอาชีพ ย้ายถิ่นฐาน และถือครองที่ดิน":"All citizens became free people, with the right to choose occupations, move residence, and hold land",
"3. การคลังและงบประมาณแผ่นดิน":"3. Finance and the National Budget",
"เจ้าภาษีนายอากรและขุนนางเก็บภาษีแยกกระจัดกระจาย ขาดการตรวจสอบ":"Tax farmers and nobles collected taxes separately in a scattered manner, with no oversight",
"ก่อตั้งหอรัษฎากรพิพัฒน์ (2416), จัดทำงบประมาณแผ่นดินเป็นครั้งแรก, กำหนดระบบเงินตราทศนิยม (บาทและสตางค์)":"Established the Ho Ratsadakorn Phiphat (Revenue Office) (2416), prepared the National Budget for the first time, established a decimal currency system (baht and satang)",
"การคลังมั่นคง แยกกระเป๋าเงินแผ่นดินออกจากพระราชทรัพย์ส่วนพระองค์":"Stable public finances, separating the state treasury from the King's privy purse",
"4. กฎหมายและการศาลสมัยใหม่":"4. Modern Law and Courts",
