"ได้ \"โมเดลพื้นฐาน\" — รู้ภาษาและความรู้โลก แต่แค่ต่อข้อความ":"Produces a \"base model\" — it knows language and world knowledge, but can only continue text",
"ข้อความที่ไม่ต้องมีคนติดป้าย เพราะ \"คำเฉลย\" คือคำถัดไปในข้อความนั้นเอง · GPT-3 ใช้ 300,000 ล้านโทเคน · Llama 3 ใช้มากกว่า 15 ล้านล้านโทเคน":"Text that needs no human labeling, because the \"answer key\" is simply the next word in the text itself · GPT-3 used 300,000 million tokens · Llama 3 used more than 15 trillion tokens",
"เป้าหมาย:":"Goal:",
"ทายโทเคนถัดไปให้แม่นที่สุด (loss เดียวกับหัวข้อ 2 แต่ใช้กับข้อความ) ·":"Predict the next token as accurately as possible (the same loss as in section 2, but applied to text) · ",
