"ขั้นนี้กินเวลาและพลังคำนวณเกือบทั้งหมดของการสร้างโมเดล":"This stage takes up almost all of the time and computing power spent building the model",
"เฉลย":"Answer",
"SFT — เรียนจากตัวอย่างที่คนเขียน":"SFT — Learning from Human-Written Examples",
"คนเขียนคำถาม + คำตอบที่ดีเป็นตัวอย่าง แล้วฝึกต่อให้โมเดลตอบแบบนั้น":"People write questions + good answers as examples, then keep training the model to answer that way",
"โมเดลเริ่ม \"ทำตามคำสั่ง\" และตอบเป็นเรื่องเป็นราว":"The model starts to \"follow instructions\" and answers coherently",
"InstructGPT ใช้คำถามราว 13,000 ข้อพร้อมคำตอบที่ผู้ติดป้ายเขียนเอง (supervised fine-tuning)":"InstructGPT used about 13,000 questions with answers written by the labelers themselves (supervised fine-tuning)",
"ยังคงเป็นการทายโทเคนถัดไป แต่ทายบน \"บทสนทนาที่ดี\" จึงเปลี่ยนนิสัยจากการต่อข้อความเว็บ เป็นการตอบคำถาม":"It is still next-token prediction, but on \"good conversations\", so its behavior shifts from continuing web text to answering questions",
"2+2 เท่ากับเท่าไร":"What is 2+2?",
"ตัวอย่างที่คนเขียน":"Human-written example",
"2+2 = 4 ครับ":"2+2 = 4.",
"RLHF — ให้คนให้คะแนน":"RLHF — Humans Rate the Answers",
"โมเดลตอบหลายแบบ คนจัดอันดับว่าแบบไหนดีกว่า แล้วฝึกโมเดลให้ได้คะแนนสูงขึ้น":"The model gives several answers, people rank which is better, then the model is trained to earn higher scores",
"ตอบตรงใจ ปลอดภัย และเป็นประโยชน์ขึ้น":"Answers that are more on target, safe, and helpful",
"InstructGPT ให้คนจัดอันดับคำตอบของคำถามราว 33,000 ข้อ เพื่อฝึก":"InstructGPT had people rank the answers to about 33,000 questions in order to train ",
"(โมเดลให้คะแนน) แล้วใช้ reinforcement learning (PPO) กับคำถามอีกราว 31,000 ข้อ ปรับโมเดลหลักให้ได้คะแนนสูง":" (a model that gives scores), then used reinforcement learning (PPO) on about 31,000 more questions to tune the main model to score highly",
"ผล:":"Result:",
"คนชอบคำตอบของ InstructGPT ขนาด 1,300 ล้านพารามิเตอร์ มากกว่า GPT-3 ขนาด 175,000 ล้าน · ปัจจุบันมีวิธีตระกูลเดียวกันอีกหลายแบบ เช่น DPO และการให้ AI ช่วยให้คะแนนตามหลักการที่เขียนไว้ (Constitutional AI)":"People preferred the answers of InstructGPT of size 1,300 million parameters over GPT-3 of size 175,000 million · Today there are several other methods in the same family, such as DPO and having an AI help score answers according to written principles (Constitutional AI)",
