"ยังไม่มีมนุษย์คนไหนเคยไปดาวอังคาร":"No human has ever been to Mars",
"— โมเดลเอาความรู้เรื่องดวงจันทร์ (Neil Armstrong, Apollo 11) มาตอบ เพราะในข้อมูลฝึก วลี \"first person to walk on…\" มักตามด้วยเรื่องดวงจันทร์ มันจึงเลือกคำที่ \"ฟังเข้ากัน\" ไม่ใช่คำที่ \"จริง\"":" — The model answered with knowledge about the Moon (Neil Armstrong, Apollo 11), because in the training data the phrase \"first person to walk on…\" is usually followed by the Moon. So it picked words that \"sound like they fit\", not words that are \"true\"",
