"แปะข่าว 1 บรรทัดไว้หน้าคำถาม (RAG)":"Paste a 1-line news item in front of the question (RAG)",
"— โมเดลตัวเดิม น้ำหนักเดิม ไม่ได้ฝึกใหม่ แค่ attention ดึงชื่อจากข่าวที่แปะไว้มาใช้":" — Same model, same weights, no retraining; attention simply pulls the name from the pasted news",
"แท่ง = ความน่าจะเป็นของโทเคนแรกของชื่อ ณ ตำแหน่งหลัง \"Thailand's Prime Minister,\" (Ying = Yingluck · An = Anutin · Pr = Prayut · Th = Thaksin) — ระบบ RAG จริงจะ \"ค้นหา\" เอกสารที่เกี่ยวข้องจากคลังอัตโนมัติก่อนแปะ":"Bar = probability of the first token of the name at the position after \"Thailand's Prime Minister,\" (Ying = Yingluck · An = Anutin · Pr = Prayut · Th = Thaksin) — a real RAG system would automatically \"search\" a document store for relevant documents before pasting them",
"ราคาทองคำแท่งวันนี้เท่าไร ถ้าซื้อ 2 บาทต้องจ่ายเท่าไร":"What is the gold bar price today? If I buy 2 baht of gold, how much do I have to pay?",
